chain = [(1, 1)]

    def backtrack(chain):
        if not remaining:
            if not chain:
                return []
            return chain if chain[-1][1] == chain[0][0] else None

        last = chain[-1][1] if chain else None
        for i, (a, b) in enumerate(remaining):
            # Swap the chosen domino out of `remaining` in place.
            remaining[i] = remaining[-1]
            remaining.pop()

            if chain:
                if a == last:
                    result = backtrack(chain + [(a, b)])
                    if result is not None:
                        return result
                if b == last:
                    result = backtrack(chain + [(b, a)])
                    if result is not None:
                        return result
            else:
                # The first domino can start in either orientation.
                for d in ((a, b), (b, a)):
